option.value:
{% extends "base.html" %}
{% block title %}Dettaglio Libro — Biblioteca{% endblock %}
{% block content %}
<script>
    const BOOK_ID = {{ book_id }};
</script>
<a href="/ui/books" class="btn btn-secondary" style="margin-bottom:1rem;display:inline-block;">← Torna al catalogo</a>
<div class="card" id="book-card">
    <p class="loading">Caricamento…</p>
</div>
<div class="card">
    <h2> Utenti che hanno questo libro</h2>
    <table>
        <thead>
            <tr><th>#</th><th>Nome</th><th>Città</th><th>Dettagli</th></tr>
        </thead>
        <tbody id="users-tbody">
            <tr><td colspan="4" class="loading">Caricamento…</td></tr>
        </tbody>
    </table>
</div>
<script>
    async function loadBookDetails() {
        const response = await fetch('/books/' + BOOK_ID);
        const book = await response.json();
        document.getElementById('book-card').innerHTML =
            '<h2>' + book.title + '</h2>' +
            '<div class="detail-attrs">' +
                '<span class="label">ID:</span><span>' + book.id + '</span>' +
                '<span class="label">Autore:</span><span>' + book.author + '</span>' +
                '<span class="label">Recensione:</span><span>' + book.review + '/5</span>' +
            '</div>' +
            '<button class="btn btn-danger" onclick="deleteBook()"> Elimina libro</button>';
    }
    async function loadBookUsers() {
        const response = await fetch('/api/books/' + BOOK_ID + '/users');
        const users = await response.json();
        const tbody = document.getElementById('users-tbody');
        tbody.innerHTML = '';
        users.forEach(function(user) {
            const row = document.createElement('tr');
            row.innerHTML =
                '<td>' + user.id + '</td>' +
                '<td>' + user.name + '</td>' +
                '<td>' + user.city + '</td>' +
                '<td><a class="link-detail" href="/ui/users/' + user.id + '">Vedi →</a></td>';
            tbody.appendChild(row);
        });
    }
    async function deleteBook() {
        if (!confirm('Eliminare questo libro?')) return;
        const response = await fetch('/books/' + BOOK_ID, { method: 'DELETE' });
        if (response.ok) {
            window.location.href = '/ui/books';
        }
    }
    document.addEventListener('DOMContentLoaded', function() {
        loadBookDetails();
        loadBookUsers();
    });
</script>
{% endblock %}

