{% extends "base.html" %}
{% block title %}Dettaglio Utente — Biblioteca{% endblock %}
{% block content %}
<script>
    const USER_ID = {{ user_id }};
</script>
<a href="/ui/users" class="btn btn-secondary" style="margin-bottom:1rem;display:inline-block;">← Torna alla lista</a>
<div class="card" id="user-card">
    <p class="loading">Caricamento…</p>
</div>
<div class="card">
    <h2> Libri presi in prestito</h2>
    <table>
        <thead>
            <tr><th>#</th><th>Titolo</th><th>Autore</th><th>Recensione</th><th>Dettagli</th></tr>
        </thead>
        <tbody id="books-tbody">
            <tr><td colspan="5" class="loading">Caricamento…</td></tr>
        </tbody>
    </table>
</div>
<script>
    async function loadUserDetails() {
        const response = await fetch('/api/users/' + USER_ID);
        const user = await response.json();
        document.getElementById('user-card').innerHTML =
            '<h2>' + user.name + '</h2>' +
            '<div class="detail-attrs">' +
                '<span class="label">ID:</span><span>' + user.id + '</span>' +
                '<span class="label">Data di nascita:</span><span>' + user.birth_date + '</span>' +
                '<span class="label">Città:</span><span>' + user.city + '</span>' +
            '</div>' +
            '<button class="btn btn-danger" onclick="deleteUser()"> Elimina utente</button>';
    }
    async function loadUserBooks() {
        const response = await fetch('/users/' + USER_ID + '/books');
        const books = await response.json();
        const tbody = document.getElementById('books-tbody');
        tbody.innerHTML = '';
        books.forEach(function(book) {
            const row = document.createElement('tr');
            row.innerHTML =
                '<td>' + book.id + '</td>' +
                '<td>' + book.title + '</td>' +
                '<td>' + book.author + '</td>' +
                '<td>' + book.review + '/5</td>' +
                '<td><a class="link-detail" href="/ui/books/' + book.id + '">Vedi →</a></td>';
            tbody.appendChild(row);
        });
    }
    async function deleteUser() {
        if (!confirm('Eliminare questo utente?')) return;
        const response = await fetch('/api/users/' + USER_ID, { method: 'DELETE' });
        if (response.ok) {
            window.location.href = '/ui/users';
        }
    }
    document.addEventListener('DOMContentLoaded', function() {
        loadUserDetails();
        loadUserBooks();
    });
</script>
{% endblock %}

